
import { NextRequest, NextResponse } from "next/server";
import { supabaseAdmin } from "@/lib/supabaseAdmin";

export async function POST(req: NextRequest) {
  try {
    const key = req.headers.get("x-admin-key");

    if (!process.env.ADMIN_KEY || key !== process.env.ADMIN_KEY) {
      return NextResponse.json(
        { error: "Unauthorized access" },
        { status: 401 }
      );
    }

    const { data: leads, error } = await supabaseAdmin
      .from("students")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) throw error;

    const students = leads || [];

    const total = students.length;

    const highIntent = students.filter(
      (student) => student.lead_category === "High"
    ).length;

    const mediumIntent = students.filter(
      (student) => student.lead_category === "Medium"
    ).length;

    const interests: Record<string, number> = {};
    const cities: Record<string, number> = {};

    students.forEach((student) => {
      (Array.isArray(student.interests)
        ? student.interests
        : []
      ).forEach((interest: string) => {
        interests[interest] = (interests[interest] || 0) + 1;
      });

      if (student.city) {
        cities[student.city] = (cities[student.city] || 0) + 1;
      }
    });

    return NextResponse.json({
      metrics: {
        total,
        highIntent,
        highIntentRate: total
          ? Number(((highIntent / total) * 100).toFixed(1))
          : 0,
        mediumIntent,
        interests,
        cities,
      },
      leads: students.map((student) => ({
        id: student.id,
        student_name: student.student_name,
        email: student.email,
        phone: student.phone,
        city: student.city,
        interests: student.interests || [],
        lead_score: student.lead_score,
        lead_category: student.lead_category,
      })),
    });
  } catch (error) {
    console.error("Analytics error:", error);

    return NextResponse.json(
      { error: "Unable to load analytics" },
      { status: 500 }
    );
  }
}
